data.minimal_example:
FloatingActionButton(
  onPressed: () {
    showMonthPicker(
      context: context,
      initialDate: DateTime.now(),
    ).then((date) {
      if (date != null) {
        setState(() {
          selectedDate = date;
        });
      }
    });
  },
  child: const Icon(Icons.calendar_today),
)
